    h, w = len(grid), len(grid[0])
    centers = []
    blank_cols = set()

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if all(grid[rr][cc] == 3 for rr, cc in
                   ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))):
                if grid[r][c] == 0:
                    blank_cols.add(c)
                elif grid[r][c] != 3:
                    centers.append((r, c, grid[r][c]))

    # Record the 3-cells that form the arms of colored crosses.
    arms = {}
    for r, c, color in centers:
        for p in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            arms[p] = (r, c)

    out = [[0] * w for _ in range(h)]

    # Draw horizontal rays, stopping at arms of other colored crosses.
    for r, c, color in centers:
        out[r][c] = color
        for dc in (-1, 1):
            j = c + dc
            while 0 <= j < w:
                owner = arms.get((r, j))
                if owner is not None and owner != (r, c):
                    break
                if j not in blank_cols:
                    out[r][j] = color
                j += dc

    # Draw vertical rays; these take precedence at intersections.
    for r, c, color in centers:
        out[r][c] = color
        for dr in (-1, 1):
            i = r + dr
            while 0 <= i < h:
                owner = arms.get((i, c))
                if owner is not None and owner != (r, c):
                    break
                out[i][c] = color
                i += dr

    # Restore all original 3 marks and colored centers.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 3
    for r, c, color in centers:
        out[r][c] = color

    return out
